mapper.select:
SELECT SN, UUID, USEYN, "TIMESTAMP", FACE_GROUP_ID, SOURCE, IMAGE_PATH, IMAGE_WIDTH, IMAGE_HEIGHT, FACE_COUNT, FACE_INDEX, TRACKING_ID, BBOX_LEFT, BBOX_TOP, BBOX_RIGHT, BBOX_BOTTOM, LANDMARK_COUNT, MESH_SCORE, HAS_IRIS, IOD_NORM, NOSE_TIP_X, NOSE_TIP_Y, LEFT_EYE_X, LEFT_EYE_Y, RIGHT_EYE_X, RIGHT_EYE_Y, MOUTH_CENTER_X, MOUTH_CENTER_Y, HEAD_EULER_X, HEAD_EULER_Y, HEAD_EULER_Z FROM FACE_MESH_INFO WHERE USEYN = 'Y' AND UUID = #{uuid}
AND FACE_GROUP_ID = #{faceGroupId}
ORDER BY SN DESC

mapper.delete:
UPDATE FACE_MESH_INFO
SET USEYN = 'N'
WHERE SN = #{sn}
AND UUID = #{uuid}
